package com.careerpilot.backend.modules.discovery.services;
import com.careerpilot.connector.sdk.*; import com.careerpilot.backend.modules.discovery.domain.*; import com.careerpilot.backend.modules.discovery.repositories.*; import com.careerpilot.backend.modules.discovery.events.DiscoveryEvents.*; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.context.ApplicationEventPublisher; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class JobDiscoveryService { private final ConnectorRegistry registry; private final DiscoveryJobRepository repo; private final TaxonomyNormalizer normalizer; private final DuplicateDetector dedupe; private final ApplicationEventPublisher events; private final JobIntelligencePort intelligence; private final ObjectMapper json; private final DiscoveryMetrics metrics;
 public JobDiscoveryService(ConnectorRegistry a,DiscoveryJobRepository b,TaxonomyNormalizer c,DuplicateDetector d,ApplicationEventPublisher e,JobIntelligencePort f,ObjectMapper g,DiscoveryMetrics h){registry=a;repo=b;normalizer=c;dedupe=d;events=e;intelligence=f;json=g;metrics=h;}
 @Transactional public SynchronizationResult discover(String connectorId,DiscoveryContext context){Connector c=registry.get(connectorId);if(!c.isEnabled())throw new IllegalStateException("Connector is disabled");var timer=metrics.start();Map<SynchronizationState,Integer> counts=new EnumMap<>(SynchronizationState.class);for(var s:SynchronizationState.values())counts.put(s,0);Set<String> seen=new HashSet<>();try{if(!c.authenticate())throw new IllegalStateException("Authentication failed");List<DiscoveredJob> jobs=Optional.ofNullable(c.discoverJobs(context)).orElse(List.of());for(DiscoveredJob raw:jobs){try{validate(raw);raw.setConnectorId(c.getConnectorId());DiscoveredJob j=normalizer.normalize(raw);j.setContentHash(dedupe.hash(j));seen.add(j.getExternalId());var old=repo.findByConnectorIdAndExternalId(j.getConnectorId(),j.getExternalId());if(old.isPresent()&&old.get().getContentHash().equals(j.getContentHash())){old.get().setLastSeenAt(Instant.now());old.get().setSynchronizationState(SynchronizationState.UNCHANGED);repo.save(old.get());inc(counts,SynchronizationState.UNCHANGED);continue;}if(old.isEmpty()&&dedupe.duplicate(j)){metrics.duplicates.increment();inc(counts,SynchronizationState.UNCHANGED);continue;}DiscoveryJob entity=map(j,old.orElse(null));SynchronizationState state=old.isPresent()?SynchronizationState.UPDATED:SynchronizationState.NEW;entity.setSynchronizationState(state);repo.save(entity);inc(counts,state);if(state==SynchronizationState.NEW){metrics.discovered.increment();events.publishEvent(new JobDiscoveredEvent(entity));}else{metrics.updated.increment();events.publishEvent(new JobUpdatedEvent(entity));}intelligence.accept(entity);}catch(Exception bad){inc(counts,SynchronizationState.FAILED);}}
 for(DiscoveryJob old:repo.findByConnectorId(connectorId)){if(!seen.contains(old.getExternalId())&&old.getSynchronizationState()!=SynchronizationState.REMOVED){old.setSynchronizationState(SynchronizationState.REMOVED);old.setUpdatedAt(Instant.now());repo.save(old);inc(counts,SynchronizationState.REMOVED);events.publishEvent(new JobRemovedEvent(old));}}
 SynchronizationResult result=SynchronizationResult.builder().connectorId(connectorId).counts(counts).build();events.publishEvent(new ConnectorSynchronizationCompletedEvent(connectorId,result,Instant.now()));metrics.duration(timer,connectorId);return result;}catch(RuntimeException ex){metrics.failures.increment();inc(counts,SynchronizationState.FAILED);SynchronizationResult fail=SynchronizationResult.builder().connectorId(connectorId).counts(counts).error(ex.getMessage()).build();events.publishEvent(new ConnectorSynchronizationCompletedEvent(connectorId,fail,Instant.now()));throw ex;}finally{c.disconnect();}}
 public List<SynchronizationResult> discoverAll(){return registry.enabled().stream().map(c->{try{return discover(c.getConnectorId(),DiscoveryContext.builder().build());}catch(Exception e){return SynchronizationResult.builder().connectorId(c.getConnectorId()).error(e.getMessage()).build();}}).toList();} public List<DiscoveryJob> jobs(){return repo.findAll();} public DiscoveryJob job(UUID id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Job not found"));}
 private void validate(DiscoveredJob j){if(j==null||blank(j.getExternalId())||blank(j.getSource())||blank(j.getTitle())||blank(j.getCompany())||blank(j.getRawContent()))throw new IllegalArgumentException("externalId, source, title, company and rawContent are required");}private boolean blank(String x){return x==null||x.isBlank();}private void inc(Map<SynchronizationState,Integer> m,SynchronizationState s){m.put(s,m.getOrDefault(s,0)+1);}private DiscoveryJob map(DiscoveredJob j,DiscoveryJob e){Instant now=Instant.now();if(e==null)e=DiscoveryJob.builder().id(UUID.randomUUID()).discoveredAt(now).build();e.setExternalId(j.getExternalId());e.setConnectorId(j.getConnectorId());e.setSource(j.getSource());e.setSourceUrl(j.getSourceUrl());e.setTitle(j.getTitle());e.setCompany(j.getCompany());e.setLocation(j.getLocation());e.setEmploymentType(j.getEmploymentType());e.setWorkMode(j.getWorkMode());e.setSalary(j.getSalary());e.setPostedDate(j.getPostedDate());e.setRawContent(j.getRawContent());try{e.setMetadataJson(json.writeValueAsString(j.getMetadata()));}catch(Exception x){e.setMetadataJson("{}");}e.setContentHash(j.getContentHash());e.setNormalizedTitle(j.getNormalizedTitle());e.setNormalizedCompany(j.getNormalizedCompany());e.setUpdatedAt(now);e.setLastSeenAt(now);return e;}}
